using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerCorruptAfflictionEnemyOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/OnPlayerCorruptAfflictionEnemy Omen Data")]
public class OnPlayerCorruptAfflictionEnemyOmenData : OmenData
{
	private const string corruptAfflictionEnemyChantID = "CorruptAfflictionEnemyChant";

	private Action<int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			ActivateOmen();
		};
		ReferenceSingleton<SothisOmensHandler>.Instance.OnPlayerSentinelCorruptAfflictionEnemyMultipleTimesOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.OnPlayerSentinelCorruptAfflictionEnemyMultipleTimesOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CorruptAfflictionEnemyChant") + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + base.OmenConvertedDescription();
	}
}
